<script lang="ts">import type { Resource } from '../../lib/api';export let accessMode:'direct'|'agent'='direct';export let url='';export let username='';export let password='';export let timeoutSeconds=10;export let tlsInsecure=false;export let mcpServerResourceId='';export let mcpServers:Resource[]=[];export let configurationAttempted=false;export let onConfigurationChange=()=>{};</script>
{#if accessMode==='agent'}<label class:invalid={configurationAttempted&&!mcpServerResourceId}><span><i>*</i>关联 MCPServer</span><select bind:value={mcpServerResourceId} on:change={onConfigurationChange}><option value="">请选择活动的 MCPServer</option>{#each mcpServers as server}<option value={server.id}>{server.name}</option>{/each}</select></label><p class="docker-field-help">RabbitMQ Agent 通过关联 MCPServer 提供统一只读工具。</p>{:else}<div class="docker-form-grid"><label class:invalid={configurationAttempted&&!url.trim()}><span><i>*</i>Management API URL</span><input bind:value={url} required on:input={onConfigurationChange} placeholder="例如 http://rabbitmq:15672" /></label><label><span>用户名</span><input bind:value={username} on:input={onConfigurationChange}/></label><label><span>密码</span><input type="password" bind:value={password} on:input={onConfigurationChange}/></label><label><span>超时时间（秒）</span><input type="number" min="1" max="300" bind:value={timeoutSeconds} on:input={onConfigurationChange}/></label><label><span>跳过 TLS 校验</span><input type="checkbox" bind:checked={tlsInsecure} on:change={onConfigurationChange}/></label></div>{/if}
